create table if not exists public.provider_health (provider_key text primary key, state text not null default 'HEALTHY' check (state in ('HEALTHY','DEGRADED','FAILING','OFFLINE','RECOVERING')), circuit_state text not null default 'CLOSED' check (circuit_state in ('CLOSED','OPEN','HALF_OPEN')), last_checked_at timestamptz not null default now(), last_success_at timestamptz, last_failure_at timestamptz, last_latency_ms integer, success_count bigint not null default 0, failure_count bigint not null default 0, consecutive_failures integer not null default 0, last_error text, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.provider_operations (operation_id uuid primary key default gen_random_uuid(), provider_key text not null, operation text not null, correlation_id text, success boolean not null, latency_ms integer, error_class text, created_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb);
create index if not exists provider_operations_provider_created_idx on public.provider_operations(provider_key, created_at desc);
create table if not exists public.autonomous_incidents (incident_id uuid primary key default gen_random_uuid(), fingerprint text not null unique, severity text not null check (severity in ('info','warning','critical')), status text not null default 'NORMAL' check (status in ('NORMAL','INVESTIGATING','CONTAINED','RECOVERING','RESOLVED')), source text not null, summary text not null, first_seen_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), occurrence_count integer not null default 1, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.autonomous_metrics (metric_key text not null, bucket_start timestamptz not null, metric_value numeric not null default 0, metadata jsonb not null default '{}'::jsonb, primary key(metric_key,bucket_start));
create table if not exists public.provider_webhook_events (provider_key text not null, event_id text not null, event_type text not null, provider_timestamp timestamptz, received_at timestamptz not null default now(), payload jsonb not null default '{}'::jsonb, stale boolean not null default false, primary key(provider_key,event_id));
create index if not exists provider_webhook_events_provider_time_idx on public.provider_webhook_events(provider_key, provider_timestamp desc);
revoke all on public.provider_health, public.provider_operations, public.autonomous_incidents, public.autonomous_metrics, public.provider_webhook_events from anon, authenticated;
grant all on public.provider_health, public.provider_operations, public.autonomous_incidents, public.autonomous_metrics, public.provider_webhook_events to service_role;
alter table public.provider_health enable row level security;
alter table public.provider_operations enable row level security;
alter table public.autonomous_incidents enable row level security;
alter table public.autonomous_metrics enable row level security;
alter table public.provider_webhook_events enable row level security;
